// ════════════════════════════════════════════════════════════
//  Exercicio 227 — Cobertura: o que os testes NAO exercitaram
//
//  Uma suite verde nao diz nada sobre o que ela nao toca. Num sistema
//  de 200 arquivos, o codigo que ninguem exercitou e exatamente onde
//  o bug mora.
//
//  Este exercicio nao mede a si mesmo — a cobertura se pede na linha
//  de comando:
//
//      dataforge test --cobertura
//      dataforge test --minimo=80        # reprova abaixo disso
//      dataforge test --cobertura --linhas
//      dataforge crucible --cobertura
//
//  O que ele mostra e o que a medicao ENXERGA, e o que ela nao.
// ════════════════════════════════════════════════════════════

adopt Arcane.OS as OS
adopt Arcane.IO as IO
adopt Arcane.Process as P

// ── 1. Um projeto pequeno, com um ramo nao testado ──────────

raiz := IO.join(OS.temp_dir(), "df_cobertura_exercicio")
given IO.exists(raiz):
    IO.remove_tree(raiz)
IO.mkdir(IO.join(raiz, "src"))
IO.mkdir(IO.join(raiz, "tests"))

IO.write(IO.join(raiz, "forge.toml"),
    '[project]\nname = "cob"\nversion = "1.0.0"\nentry = "src/main.df"\n')

IO.write(IO.join(raiz, "src", "conta.df"), """
action taxa(valor, tipo):
    given tipo is "premium":
        yield valor * 0.01
    orif tipo is "comum":
        yield valor * 0.03
    yield valor * 0.05

action nunca_chamada(x):
    yield x * 2

relay taxa, nunca_chamada
""")

IO.write(IO.join(raiz, "src", "main.df"), """
adopt ./conta as C

out C.taxa(100, "comum")
""")

IO.write(IO.join(raiz, "tests", "conta_test.df"), """
adopt Arcane.Test as T
adopt ../src/conta as C

action test_premium():
    T.assert_eq(C.taxa(100, "premium"), 1.0)
""")

// ── 2. Medir ────────────────────────────────────────────────

r := P.run(["dataforge", "test", "--cobertura", "--linhas", "--no-color"],
    cwd := raiz)
saida := r["stdout"]

// So a secao de cobertura interessa: o nome do arquivo de teste
// aparece na linha de resultado dele, que e outra coisa.
// A barra invertida do Windows vira barra: o relatorio mostra o
// caminho como o SISTEMA o escreve, e um teste que procura "src/conta"
// passa em Linux e reprova no Windows.
relatorio := saida.split("Cobertura")[1].replace("\\", "/")

// O arquivo de codigo e medido; o de teste, nao — o que interessa
// medir e o codigo, nao a suite.
assert "src/conta.df" in relatorio
assert "conta_test.df" not in relatorio

// A acao que ninguem chamou aparece POR NOME. E a informacao que
// resolve: "58% coberto" nao diz o que fazer; "sem teste:
// nunca_chamada" diz.
assert "nunca_chamada" in relatorio

// E as linhas descobertas saem em faixas — uma lista de setenta
// numeros e ilegivel.
assert "linhas:" in relatorio

// ── 3. O minimo reprova, e isso e o que serve no CI ─────────

alto := P.run(["dataforge", "test", "--minimo=95", "--no-color"], cwd := raiz)
assert alto["exit_code"] is 1
assert "abaixo do mínimo" in alto["stdout"]

baixo := P.run(["dataforge", "test", "--minimo=10", "--no-color"], cwd := raiz)
assert baixo["exit_code"] is 0

// ── 4. O que a medicao NAO ve ───────────────────────────────
//
// Ela e de LINHA, e nao de ramo: 'given a and b' conta como coberta
// mesmo que 'b' nunca tenha sido avaliado. Medir ramo dobraria o
// custo, e cobertura de linha ja responde a pergunta que importa —
// "existe codigo que ninguem testou".
//
// Duas escolhas que mudam o que o numero diz:
//
//   - a linha do 'action' nao conta, so o corpo. Uma acao nunca
//     chamada aparece com 0%, e nao com 20%.
//   - um arquivo que NENHUM teste toca aparece com 0% em vez de sumir
//     do relatorio. Sumir e o que faz uma cobertura de 95% conviver
//     com metade do sistema sem teste.

assert "0.0%" in relatorio  // o main.df, que nenhum teste importa

IO.remove_tree(raiz)
out "225 ok — cobertura"

// ════════════════════════════════════════════════════════════
//  Exercicio 228 — Instantaneo, banco isolado e teste instavel
//
//  Tres ferramentas do Crucible para o que um teste comum nao alcanca
//  bem: resultado grande, estado que sobra entre testes, e falha que
//  vai e volta.
// ════════════════════════════════════════════════════════════

adopt Crucible
adopt Arcane.Database as Banco

// ── 1. O banco de exemplo ───────────────────────────────────

db := Banco.memory()
Banco.create_table(db, "livros", {
        "id": "INTEGER PRIMARY KEY AUTOINCREMENT",
        "titulo": "TEXT NOT NULL",
        "preco": "REAL NOT NULL"
    })
Banco.insert_many(db, "livros", [
        {"titulo": "Duna", "preco": 79.9},
        {"titulo": "Neuromancer", "preco": 64.9}
    ])

action relatorio():
    linhas := Banco.aggregate(db, "livros",
        {"quantos":["count", "*"],
            "total":["sum", "preco"]})
    yield {"acervo": linhas[0]["quantos"], "valor": linhas[0]["total"]}

// ── 2. Instantaneo ──────────────────────────────────────────
//
// Para o que e grande demais para escrever a mao no teste: o HTML de
// uma pagina, o relatorio de trinta linhas, o JSON de uma rota.
// Escrever o esperado a mao para isso da um teste que ninguem mantem.
//
// Na PRIMEIRA vez ele grava e passa — e o unico jeito de comecar. O
// arquivo vai no controle de versao, e e no diff do commit que alguem
// confere se o novo esperado esta certo.
//
// Para aceitar uma mudanca intencional:
//     DF_ATUALIZAR_SNAPSHOT=1 dataforge crucible
//
// Atualizar por padrao seria pior que nao ter instantaneo: o teste
// passaria sempre, gravando o errado por cima do certo.

crucible "o relatorio":
    trial "nao muda sem aviso":
        Crucible.snapshot("relatorio_do_acervo", relatorio())

    trial "e o texto grande tambem entra":
        html := "<table>\n  <tr><td>Duna</td></tr>\n</table>"
        Crucible.snapshot("tabela_html", html)

// ── 3. Banco que se desfaz ──────────────────────────────────
//
// O problema: um teste que grava deixa a linha la, e o teste seguinte
// a encontra. A suite passa na ordem em que foi escrita e falha em
// qualquer outra — e '--aleatorio' expoe isso de um jeito que parece
// intermitente.
//
// 'Crucible.banco(db)' abre uma transacao e a desfaz no fim do trial,
// SEMPRE. Apagar tudo entre testes seria a alternativa, e e mais lenta
// e mais fragil: ela precisa saber a ordem das chaves estrangeiras.

crucible "isolamento de banco":
    Crucible.before(lambda suite: Crucible.banco(db))

    trial "um teste que grava":
        Banco.insert(db, "livros", {"titulo": "Solaris", "preco": 54.9})
        Crucible.expect(Banco.count(db, "livros")).to_be(3)

    trial "e o seguinte nao ve o que ele gravou":
        Crucible.expect(Banco.count(db, "livros")).to_be(2)

    trial "nem na ordem inversa":
        Banco.insert(db, "livros", {"titulo": "Fundacao", "preco": 49.9})
        Crucible.expect(Banco.count(db, "livros")).to_be(3)

// ── 4. Teste instavel ──────────────────────────────────────
//
// Existe para o que depende de rede, de relogio ou de escalonamento —
// e NAO para esconder um bug. Ele conta as tentativas: um teste que
// precisa de tres toda vez nao e instavel, esta quebrado, e o numero e
// o que denuncia isso.

crucible "instabilidade":
    trial "tenta de novo antes de desistir":
        tentativas := {"n": 0}

        action falha_duas_vezes():
            tentativas["n"] := tentativas["n"] + 1
            given tentativas["n"] smaller 3:
                trigger "a rede ainda nao respondeu"
            yield yes

        r := Crucible.flaky(falha_duas_vezes, 5)
        Crucible.expect(r["ok"]).to_be(yes)
        Crucible.expect(r["tentativas"]).to_be(3)

    trial "e desiste depois do limite":
        // 'to_raise' nao serve aqui: o que 'flaky' levanta ao desistir
        // e a propria falha de expectativa do Crucible, e ela e o
        // sinal de teste reprovado — nao um erro a capturar.
        desistiu := no
        monitor:
            Crucible.flaky(lambda: trigger("sempre falha"), 2)
        handle Error as e:
            desistiu := "2 tentativas" in e.message
        Crucible.expect(desistiu).to_be(yes)

// ── 5. Rodar ────────────────────────────────────────────────
//
// Fora do 'dataforge crucible', os instantaneos precisam saber de qual
// arquivo sao — quem roda pelo comando nao precisa disto.

Crucible.snapshot_dir(__file__)
r := Crucible.run()
assert r["falhou"] is 0, $"{r["falhou"]} falharam"
assert r["erro"] is 0
assert r["passou"] is 7

out "226 ok — instantaneo e isolamento"

// ════════════════════════════════════════════════════════════
//  Exercicio 229 — Depurar sem 'out'
//
//  'out' no meio do codigo e o depurador mais usado do mundo, e ele
//  tem tres defeitos: muda o que voce esta medindo, tem de ser
//  removido depois, e nao mostra o que voce NAO pensou em imprimir.
//
//  Este exercicio nao usa o depurador interativo — ele exige um
//  terminal ou um editor. Ele exercita as DUAS pecas em que o
//  depurador se apoia, e que dao para verificar com 'assert': saber
//  quais linhas sao executaveis, e ler o valor no quadro certo.
// ════════════════════════════════════════════════════════════

// ── O programa que vamos investigar ─────────────────────────
//
// Ele tem um bug de verdade: a media de uma lista vazia.

action media(nums):
    soma := 0
    cycle n in nums:
        soma := soma + n
    yield soma / len(nums)

// ── 1. O erro diz o arquivo, a linha e a coluna ─────────────
//
// E o primeiro depurador: um stack trace que aponta o lugar.

monitor:
    media([])
    assert no  // nao chega aqui
handle Error as e:
    assert e.type is "DivisionByZeroError"
    // A linha e a do 'yield', dentro da acao — e nao a da chamada.
    assert e.line is 22

// ── 2. A pilha diz quem chamou quem ─────────────────────────
//
// Numa acao chamada de cinco lugares, "deu erro em media()" nao
// ajuda: o que importa e QUAL das cinco chamadas.

action relatorio(vendas):
    yield media(vendas)

monitor:
    relatorio([])
handle Error as e:
    nomes := [q["name"] cycle q in e.stack]
    assert "media" in nomes
    assert "relatorio" in nomes
    // Do mais externo para o mais interno: e a ordem em que se le
    // "quem chamou quem".
    assert nomes.index("relatorio") smaller nomes.index("media")

// ── 3. Consertado, com o caso que faltava ───────────────────

action media2(nums):
    given len(nums) is 0:
        yield 0.0
    soma := 0
    cycle n in nums:
        soma := soma + n
    yield soma / len(nums)

assert media2([]) is 0.0
assert media2([2, 4, 6]) is 4.0

// ── 4. 'defer' mostra sem sujar o caminho de saida ──────────
//
// Um 'out' antes de cada 'yield' precisa ser repetido em cada saida
// da acao — e a que voce esquecer e justamente a que da errado.
// 'defer' roda na saida, qualquer uma delas.

saidas := []

action classificar(n):
    // 'defer' abre BLOCO — nao aceita expressao na mesma linha.
    defer:
        saidas.append($"classificar({n}) saiu")
    given n smaller 0:
        yield "negativo"
    given n is 0:
        yield "zero"
    yield "positivo"

assert classificar(-5) is "negativo"
assert classificar(0) is "zero"
assert classificar(7) is "positivo"

// Tres saidas diferentes, tres registros — nenhum esquecido.
assert len(saidas) is 3
assert saidas[0] is "classificar(-5) saiu"

// ── 5. A pilha atravessa 'monitor' aninhado ─────────────────
//
// O quadro onde o erro NASCEU e o que importa, e nao o ponto onde
// alguem decidiu capturar. Um 'handle' tres niveis acima ainda ve o
// caminho inteiro.

action nivel3():
    trigger "o disco encheu"

action nivel2():
    yield nivel3()

action nivel1():
    monitor:
        yield nivel2()
    handle RuntimeError:
        // NAO pega: 'trigger' levanta TriggerError. A armadilha 18.
        yield "nao passa por aqui"

monitor:
    nivel1()
    assert no
handle Error as e:
    nomes := [q["name"] cycle q in e.pilha]
    assert nomes is ["nivel1", "nivel2", "nivel3"]

    // Cada quadro diz onde estava a chamada — arquivo inclusive, que e
    // o que faz a pilha servir num projeto de 200 arquivos.
    cycle q in e.pilha:
        assert q["line"] bigger 0
        assert "229_depurar" in q["file"]

// ── 6. Duas linhas diferentes, e as duas estao certas ──────
//
// E a confusao mais comum ao ler uma pilha:
//
//   e.line          onde o erro NASCEU
//   quadro["line"]  onde a CHAMADA foi feita
//
// Sao numeros diferentes de propósito. Para consertar, voce quer o
// primeiro; para entender por que aquela acao foi chamada com aquele
// argumento, o segundo.

monitor:
    media([])
handle Error as e:
    // Onde estourou: dentro de 'media', no 'yield'.
    assert e.line is 22

    // Onde 'media' foi chamada: aqui, DEPOIS da declaracao — e por
    // isso o numero e maior. Sao dois numeros diferentes, e as duas
    // respostas estao certas para perguntas diferentes.
    assert e.pilha[0]["name"] is "media"
    assert e.pilha[0]["line"] bigger e.line

    // E o arquivo, em cada quadro. Uma acao declarada num arquivo e
    // chamada de outro ja reportou a linha certa com o NOME do arquivo
    // errado — e isso manda a pessoa depurar o arquivo errado.
    assert "229_depurar.df" in e.pilha[0]["file"]

out "229 ok — depurar"

32-microservicos.codigo:
// ════════════════════════════════════════════════════════════
//  Exercicio 230 — Chamada entre servicos que nao mente
//
//  Uma chamada de acao ou funciona, ou levanta. Uma chamada de REDE
//  tem um terceiro estado: NAO SE SABE. Ela pode ter chegado e a
//  resposta se perdido; pode estar a caminho; pode ter sido
//  processada duas vezes.
//
//  Este exercicio sobe DOIS servicos de verdade e exercita os quatro
//  problemas que separam um cliente que funciona de um que parece.
// ════════════════════════════════════════════════════════════

adopt Arcane.Malha as Malha
adopt Kiln

// ── O servico de baixo: estoque ─────────────────────────────
//
// Ele se comporta mal de proposito: cada rota e um dos casos.

estoque := {"CAF-500": 20, "ACU-1KG": 50}
instavel := {"vezes": 0}
recebidos := []

server servico_estoque on 0:
    route GET "/estoque/:sku":
        recebidos.append(headers["x-request-id"] ?? "")
        sku := params["sku"]
        given sku not in estoque:
            respond 404 json {"erro": "nao existe"}
        respond json {"sku": sku, "quantidade": estoque[sku]}

    route GET "/instavel":
        // Falha duas vezes e passa na terceira — como um servico que
        // esta subindo.
        //
        // O 'check' avisa que 'instavel' e escrito numa rota e vem de
        // fora, e esta certo: o Kiln atende um pedido por thread. Aqui
        // os pedidos sao SEQUENCIAIS — o cliente espera cada resposta
        // antes da proxima —, entao nao ha duas threads na mesma
        // linha. Num servidor de verdade, 'Conc.contador()'.
        // df: permitir escrita-concorrente
        instavel["vezes"] := instavel["vezes"] + 1
        given instavel["vezes"] smaller 3:
            respond 503 json {"erro": "ainda subindo"}
        respond json {"tentativas": instavel["vezes"]}

    route GET "/quebrado":
        respond 500 json {"erro": "quebrado"}

    route POST "/reservas":
        respond 201 json {
            "reservado": yes,
            "chave": headers["idempotency-key"] ?? "",
            "rastro": headers["x-request-id"] ?? ""
        }

porta := Kiln.serve(servico_estoque, 0)

// ── 1. Descoberta: nao cravar a URL no codigo ───────────────

Malha.registrar("estoque", $"http://127.0.0.1:{porta}", {
        "prazo": 2.0,
        "tentativas": 4,
        "recuo": 0.01,
        "disjuntor": {"falhas": 3, "espera": 0.4}
    })

cliente := Malha.de("estoque")

// O MESMO cliente, sempre: o disjuntor e as metricas vivem NELE, e um
// cliente novo por chamada esqueceria que o servico esta caido.
assert Malha.de("estoque") is cliente

// ── 2. A chamada, e o vault que ela devolve ─────────────────

r := cliente.get("/estoque/CAF-500")
assert r["ok"]
assert r["status"] is 200
assert r["body"]["quantidade"] is 20
assert r["tentativas"] is 1
assert r["ms"] bigger 0

// Um erro de rede devolve VAULT, e nao levanta: quem chama um servico
// precisa decidir o que fazer, e um 'monitor' em volta de cada chamada
// seria ruido.
sumido := Malha.cliente("http://127.0.0.1:1", {"tentativas": 1}).get("/x")
assert not sumido["ok"]
assert sumido["status"] is 0  // NAO CHEGOU — o terceiro estado

// ── 3. Retry: so o que e seguro ─────────────────────────────

// Um 503 e repetido: o problema e do outro lado.
r3 := cliente.get("/instavel")
assert r3["ok"]
assert r3["tentativas"] is 3

// Um 404 NAO e repetido: o pedido esta errado, e mandar de novo da o
// mesmo erro com mais latencia.
r4 := cliente.get("/estoque/NAO-EXISTE")
assert r4["status"] is 404
assert r4["tentativas"] is 1

// ── 4. O disjuntor ──────────────────────────────────────────
//
// Sem ele, um servico que cai LEVA os que dependem dele: cada pedido
// espera o prazo inteiro antes de falhar, as threads acabam, e o que
// estava de pe cai tambem.

// Retry e disjuntor SE SOMAM, e e facil errar a conta: o disjuntor
// conta cada TENTATIVA, nao cada chamada. Com 'tentativas := 4' e
// 'falhas := 3', a PRIMEIRA chamada ja abre o disjuntor — ela sozinha
// produziu quatro falhas.
r_quebrado := cliente.get("/quebrado")
assert r_quebrado["status"] is 500
assert r_quebrado["tentativas"] is 4
assert cliente.disjuntor.estado is "aberto"
assert cliente.disjuntor.falhas bigger_eq 3

// Com o disjuntor aberto, a chamada NAO SAI.
antes := len(recebidos)
r5 := cliente.get("/estoque/CAF-500")
assert not r5["ok"]
assert r5["status"] is 0
assert r5["tentativas"] is 0
assert "disjuntor aberto" in r5["erro"]
assert len(recebidos) is antes  // nada chegou do outro lado

// Depois da espera, ele ENTREABRE — deixa UMA passar. Abrir tudo de
// uma vez derrubaria o servico no instante em que ele volta.
wait 500
assert cliente.disjuntor.estado is "entreaberto"

r6 := cliente.get("/estoque/CAF-500")
assert r6["ok"]
assert cliente.disjuntor.estado is "fechado"

// Um 4xx NAO abre o disjuntor: nao e falha do SERVICO, o pedido esta
// errado. Contar isso abriria o disjuntor por um bug de quem chama.
cycle i from 1 to 5:
    cliente.get("/estoque/NAO-EXISTE")
assert cliente.disjuntor.estado is "fechado"

// ── 5. O rastro atravessa a fronteira ───────────────────────
//
// Sem um identificador que viaja com o pedido, investigar um incidente
// em cinco servicos e cruzar horario de log — o que e impossivel
// quando dois pedidos acontecem no mesmo segundo.

Malha.comecar_contexto(void, "pedidos", {"tenant": "acme"})
meu := Malha.rastro()
assert len(meu) bigger 8

cliente.get("/estoque/CAF-500")
assert recebidos[len(recebidos) - 1] is meu

// ── 6. Idempotencia: o que torna o POST seguro de repetir ───

r7 := cliente.post("/reservas", {"sku": "CAF-500", "quantidade": 2},
    chave := $"pedido-{meu[0:8]}")
assert r7["ok"]
assert r7["body"]["chave"] is $"pedido-{meu[0:8]}"
assert r7["body"]["rastro"] is meu

Malha.terminar_contexto()

// ── 7. Propagar: a metade que falta ─────────────────────────
//
// Na BORDA, o servico continua o rastro que chegou. Sem isso, cada
// servico comeca um rastro novo e a corrente se quebra.

fingido := {"headers": {"x-request-id": "veio-de-fora",
        "x-ctx-tenant": "acme"},
    "state": {}}
Malha.propagar(fingido, "estoque")
assert Malha.rastro() is "veio-de-fora"
assert Malha.contexto()["extra"]["tenant"] is "acme"
assert fingido["state"]["rastro"] is "veio-de-fora"
Malha.terminar_contexto()

// ── 8. Observar ─────────────────────────────────────────────

resumo := cliente.resumo()
assert resumo["servico"] is "estoque"
assert resumo["chamadas"] bigger 5
assert resumo["recusadas"] is 1  // so a r5: as 404 nao contam
assert resumo["disjuntor"]["estado"] is "fechado"

// E o que um incidente pergunta primeiro: quais dependencias deste
// servico estao de pe?
saude := Malha.saude()
assert len(saude) bigger_eq 1

Kiln.stop(servico_estoque)
out "227 ok — malha"

// ════════════════════════════════════════════════════════════
//  Exercicio 231 — Saga: nao existe transacao que atravesse a rede
//
//  'BEGIN' no servico de estoque nao alcanca o de cobranca. Se o
//  pedido reserva o produto e a cobranca falha, o produto fica preso
//  para sempre — e nao ha 'rollback' que chegue la.
//
//  A unica resposta correta e COMPENSAR: cada passo declara como se
//  desfaz, e uma falha no meio desfaz em ordem inversa o que ja
//  aconteceu.
// ════════════════════════════════════════════════════════════

adopt Arcane.Malha as Malha

// ── Os "servicos", com o estado que eles guardam ────────────

estoque := {"CAF-500": 10}
reservas := {}
cobrancas := {}
despachos := []
chaves_vistas := {}

action reservar(estado, chave):
    sku := estado["sku"]
    given estoque[sku] smaller estado["quantidade"]:
        trigger $"estoque insuficiente de {sku}"
    estoque[sku] := estoque[sku] - estado["quantidade"]
    reservas[chave] := estado["quantidade"]
    yield {"reserva": chave}

action liberar(estado, chave):
    given chave in reservas:
        estoque[estado["sku"]] := estoque[estado["sku"]] + reservas[chave]
        reservas.delete(chave)

action cobrar(estado, chave):
    // A chave de idempotencia faz o trabalho aqui: repetir a saga
    // depois de uma queda NAO cobra duas vezes.
    given chave in chaves_vistas:
        yield {"cobranca": chaves_vistas[chave], "repetida": yes}
    valor := estado["quantidade"] * 32.5
    given valor bigger estado["limite"]:
        trigger $"limite excedido: {valor} bigger {estado['limite']}"
    cobrancas[chave] := valor
    chaves_vistas[chave] := valor
    yield {"cobranca": valor}

action estornar(_estado, chave):
    given chave in cobrancas:
        cobrancas.delete(chave)
        chaves_vistas.delete(chave)

action despachar(estado, chave):
    despachos.append({"sku": estado["sku"], "chave": chave})
    yield {"despacho": len(despachos)}

action cancelar_despacho(_estado, _chave):
    despachos.clear()

// ── 1. O caminho feliz ──────────────────────────────────────

s := Malha.saga("checkout")
s.passo("reservar", reservar, liberar)
s.passo("cobrar", cobrar, estornar)
s.passo("despachar", despachar, cancelar_despacho)

// ANTES de rodar: nenhum passo que escreve pode ficar sem compensacao.
// Um passo assim nao falha em teste feliz — ele so aparece no dia em
// que o passo seguinte falha, e ai ja escreveu.
assert s.conferir() is []

r := s.executar({"sku": "CAF-500", "quantidade": 2, "limite": 100.0})

assert r["ok"]
assert r["concluidos"] is ["reservar", "cobrar", "despachar"]
assert r["desfeitos"] is []
assert r["orfas"] is []
assert estoque["CAF-500"] is 8
assert len(cobrancas) is 1
assert len(despachos) is 1

// O estado ATRAVESSA os passos: 'cobrar' viu o que 'reservar' devolveu.
assert r["estado"]["cobranca"] is 65.0
assert "reserva" in r["estado"]

// ── 2. A falha no meio, e a ordem do desfazimento ───────────

estoque := {"CAF-500": 10}
reservas := {}
cobrancas := {}
chaves_vistas := {}
despachos := []
ordem := []

action reservar2(estado, chave):
    estoque["CAF-500"] := estoque["CAF-500"] - estado["quantidade"]
    reservas[chave] := estado["quantidade"]
    yield void

action liberar2(_estado, chave):
    ordem.append("liberar")
    estoque["CAF-500"] := estoque["CAF-500"] + reservas[chave]
    reservas.delete(chave)

action cobrar2(_estado, chave):
    cobrancas[chave] := 99.0
    yield void

action estornar2(_estado, chave):
    ordem.append("estornar")
    cobrancas.delete(chave)

action despachar2(_estado, _chave):
    trigger "transportadora fora do ar"

s2 := Malha.saga("checkout")
s2.passo("reservar", reservar2, liberar2)
s2.passo("cobrar", cobrar2, estornar2)
s2.passo("despachar", despachar2, cancelar_despacho)

r2 := s2.executar({"sku": "CAF-500", "quantidade": 3})

// Ela NAO levanta: levantar perderia a informacao de quanto conseguiu
// desfazer, que e exatamente o que se precisa saber.
assert not r2["ok"]
assert r2["falhou_em"] is "despachar"
assert "transportadora" in r2["erro"]

// Ordem INVERSA. Estornar a cobranca antes de liberar o estoque
// deixaria uma janela em que o cliente nao tem dinheiro nem produto.
assert r2["desfeitos"] is ["cobrar", "reservar"]
assert ordem is ["estornar", "liberar"]

// E o mundo voltou ao que era.
assert estoque["CAF-500"] is 10
assert len(reservas) is 0
assert len(cobrancas) is 0
assert len(despachos) is 0

// O passo que FALHOU nao e compensado: ele nao concluiu, e desfazer o
// que nao aconteceu e o outro lado do mesmo bug.
assert "despachar" not in r2["desfeitos"]

// ── 3. Uma compensacao que falha nao pode ser engolida ──────
//
// Um estorno que nao passa deixa o sistema inconsistente, e isso
// precisa chegar a um humano.

action estornar_quebrado(_estado, _chave):
    trigger "gateway recusou o estorno"

liberou := {"sim": no}

action liberar3(_estado, _chave):
    liberou["sim"] := yes

s3 := Malha.saga("checkout")
s3.passo("reservar", reservar2, liberar3)
s3.passo("cobrar", cobrar2, estornar_quebrado)
s3.passo("despachar", despachar2, cancelar_despacho)

r3 := s3.executar({"sku": "CAF-500", "quantidade": 1})

assert not r3["ok"]
assert len(r3["orfas"]) is 1
assert r3["orfas"][0]["passo"] is "cobrar"
assert "gateway" in r3["orfas"][0]["erro"]

// A compensacao seguinte AINDA rodou: o estoque preso por um estorno
// que nao passou seria um segundo problema criado pelo primeiro.
assert liberou["sim"]
assert r3["desfeitos"] is ["reservar"]

// ── 4. Idempotencia: repetir a saga nao cobra duas vezes ────
//
// Uma saga que cai no meio precisa poder ser repetida. Sem chave
// estavel, repetir cobra de novo.

estoque := {"CAF-500": 10}
reservas := {}
cobrancas := {}
chaves_vistas := {}
despachos := []

// O MESMO identificador — e o que torna a chave de cada passo estavel
// entre execucoes.
acao := "pedido-4711"

s4 := Malha.saga("checkout", acao)
s4.passo("reservar", reservar, liberar)
s4.passo("cobrar", cobrar, estornar)

assert s4.chave_de("cobrar") is "pedido-4711:cobrar"

a := s4.executar({"sku": "CAF-500", "quantidade": 2, "limite": 100.0})
assert a["ok"]
assert len(cobrancas) is 1

// Repete a saga inteira, como faria quem reprocessa uma fila.
s5 := Malha.saga("checkout", acao)
s5.passo("reservar", reservar, liberar)
s5.passo("cobrar", cobrar, estornar)
b := s5.executar({"sku": "CAF-500", "quantidade": 2, "limite": 100.0})

assert b["ok"]
assert b["estado"]["repetida"]  // 'cobrar' reconheceu a chave
assert len(cobrancas) is 1  // NAO cobrou duas vezes

// A reserva, porem, aconteceu DE NOVO — ela e indexada pela mesma
// chave, mas o estoque foi debitado duas vezes. Idempotencia e uma
// promessa que cada servico faz por si: a saga da a chave, quem honra
// e o outro lado.
assert estoque["CAF-500"] is 6

// ── 5. O passo que escreve sem compensacao ──────────────────

s6 := Malha.saga("risco")
s6.passo("consultar", lambda e, c: {"score": 700}, escreve := no)
s6.passo("marcar", lambda e, c: void)

// 'consultar' e uma leitura e declara isso; 'marcar' escreve e nao
// disse como se desfaz.
assert s6.conferir() is ["marcar"]

// ── 6. O diario: onde isso parou ────────────────────────────

linhas := []

s7 := Malha.saga("checkout", "p-1", lambda linha: linhas.append(linha))
s7.passo("reservar", reservar2, liberar2)
s7.passo("cobrar", cobrar2, estornar2)
s7.passo("despachar", despachar2, cancelar_despacho)
s7.executar({"sku": "CAF-500", "quantidade": 1})

situacoes := [linha["situacao"] cycle linha in linhas]
assert situacoes is ["feito", "feito", "falhou", "desfeito", "desfeito"]
assert linhas[0]["passo"] is "reservar"
assert linhas[2]["passo"] is "despachar"

// O diario e gravado a CADA passo, e nao no fim: uma queda do processo
// no meio da saga perderia o que ja foi feito, e ninguem saberia o que
// compensar.
assert len(linhas) is len(s7.diario)

out "228 ok — saga"

33-lavra.codigo:
// Exercicio 233 — Lavra: o N+1, os limites e a paginacao
// Enunciado: conte as idas ao banco e prove que o lote as junta numa so.

adopt Arcane.Lavra as Lavra

record Cliente:
    id: Integer
    nome: String

record Pedido:
    id: Integer
    cliente_id: Integer

clientes := {1: Cliente(1, "Ana"), 2: Cliente(2, "Bia")}
pedidos := [Pedido(n, 1 given n % 2 is 1 otherwise 2) cycle n in range(1, 21)]

// ── 1. O problema do N+1 ──
//
// Uma consulta que pede 20 pedidos e, de cada um, o cliente, faz 21
// idas ao banco: uma para os pedidos e uma por cliente. O servidor
// parece rapido e o banco morre.
//
// Aqui a lista 'idas' CONTA — sem contar, um lote que devolve o valor
// certo e mesmo assim consulta vinte vezes passaria despercebido.
idas := []

action buscar_clientes(ids):
    idas.append(len(ids))
    yield [clientes[i] cycle i in ids]

esq := Lavra.esquema("n1")
Lavra.tipo(esq, Cliente)
Lavra.tipo(esq, Pedido)
Lavra.campo(esq, "Cliente", "nome", "String!")
Lavra.campo(esq, "Pedido", "id", "Integer!")

// O resolvedor nao BUSCA — ele PEDE. Os pedidos da mesma volta sao
// juntados num so.
// Este precisa do 'ctx' — e o ctx e o TERCEIRO. Nao da para pular o do
// meio, entao o '_args' diz que ele esta ali de proposito.
action cliente_do_pedido(p, _args, ctx):
    yield Lavra.pedir(ctx, "clientes", p.cliente_id)

Lavra.campo(esq, "Pedido", "cliente", "Cliente!", resolve := cliente_do_pedido)
Lavra.busca(esq, "pedidos", "[Pedido!]!",
    args := {"limite": {"tipo": "Integer", "padrao": 20}},
    resolve := lambda r, a, c => pedidos[0:a["limite"]])
Lavra.conferir(esq)

// O lote vive no CONTEXTO, e morre com a consulta. Um lote de processo
// guardaria o cliente depois que ele mudou, e serviria o valor velho
// para outra pessoa.
ctx := Lavra.contexto({})
_ := Lavra.lote(ctx, "clientes", buscar_clientes)

r := Lavra.executar(esq, """
busca:
    pedidos:
        id
        cliente:
            nome
    """, contexto := ctx)

out $"20 pedidos, {len(idas)} ida(s) ao banco"
assert len(r["dados"]["pedidos"]) is 20, "os vinte vieram"
assert len(idas) is 1, "UMA ida — sem o lote seriam 20"
assert idas[0] is 2, "e ela levou as duas chaves distintas"
out r["extensoes"]["lotes"]

// ── 2. Os limites ──
//
// Um grafo com ciclo deixa pedir 'pedido.cliente.pedidos.cliente…'
// para sempre. E a forma mais barata de derrubar um servidor de
// consulta, e descobrir isso RESOLVENDO ja e tarde.
_ := Lavra.limites(esq, profundidade := 2)

fundo := Lavra.executar(esq, """
busca:
    pedidos:
        cliente:
            nome
""")
out fundo["erros"][0]["mensagem"]
assert fundo["dados"] is void, "recusada antes de resolver"
assert "profundidade" in fundo["erros"][0]["mensagem"]

_ := Lavra.limites(esq, profundidade := 12)

// ── 3. Paginacao por cursor ──
//
// Paginar por posicao ('pule 3, traga 3') quebra do jeito mais dificil
// de ver: se alguem insere uma linha entre a pagina 1 e a 2, um item
// DESAPARECE — ele desceu para a posicao que ja foi lida.
p1 := Lavra.pagina(pedidos, primeiros := 3)
assert len(p1["itens"]) is 3
assert p1["info"]["tem_proxima"], "ha mais"

p2 := Lavra.pagina(pedidos, primeiros := 3, depois := p1["info"]["cursor_fim"])
out [i.id cycle i in p2["itens"]]
assert p2["itens"][0].id is 4, "continua exatamente onde parou"
assert p2["total"] is 20, "o total nao depende da pagina"

// ── 4. O erro parcial ──
//
// Quem pediu dois campos e teve problema em um recebe UM — e nao zero.
Lavra.campo(esq, "Cliente", "risco", "String",
    resolve := lambda c, a, ctx => Lavra.erro("o servico de risco caiu"))

ctx2 := Lavra.contexto({})
_ := Lavra.lote(ctx2, "clientes", buscar_clientes)

parcial := Lavra.executar(esq, """
busca:
    pedidos(limite: 1):
        cliente:
            nome
            risco
    """, contexto := ctx2)

out parcial["erros"][0]["caminho"], "|", parcial["erros"][0]["mensagem"]
assert parcial["dados"]["pedidos"][0]["cliente"]["nome"] is "Ana", "o resto veio"
assert parcial["dados"]["pedidos"][0]["cliente"]["risco"] is void
assert len(parcial["erros"]) is 1

out "230 ok"

